#include <atcoder/modint.hpp>
using mint = atcoder::modint998244353;

#ifdef DEBUG
const int debug = 1;
#else
const int debug = 0;
#endif

using ll = int64_t;
using P = pair<ll, ll>;

const ll FOD = 998244353;

ll n, m;
string s;
vector<ll> a, b;

void output (const ll x) {
	cout << x << "\n";
}
void output (const mint x) {
	cout << x.val() << "\n";
}

vector<mint> frac, invf;
void f_init (const ll n) {
	frac.resize(n+1);
	invf.resize(n+1);

	frac[0] = 1;
	for (ll i = 1; i <= n; i++) {
		frac[i] = frac[i-1] * i;
	}
	invf[n] = frac[n].inv();
	for (ll i = n; i >= 1; i--) {
		invf[i-1] = invf[i] * i;
	}
	assert(invf[0] == 1);
}
mint ncr (const ll n, const ll r) {
	if (!(n >= r && r >= 0)) return 0;
	return frac.at(n) * invf.at(r) * invf.at(n-r);
}

class dsu {
	private:
	const ll n;
	struct DSUnode {
		ll p;
		ll sz;
	};
	vector<DSUnode> dnodes;

	public:
	dsu (const ll n_): n(n_) {
		dnodes.resize(n);
		for (ll i = 0; i < n; i++) {
			dnodes[i] = {p: i, sz: 1};
		}
	}

	ll find (const ll x) {
		if (dnodes.at(x).p == x) return x;
		return dnodes.at(x).p = find(dnodes.at(x).p);
	}

	bool unite (ll l, ll r) {
		l = find(l);
		r = find(r);
		if (l == r) return false;

		if (dnodes[l].sz < dnodes[r].sz) swap(l, r);

		dnodes[l].sz += dnodes[r].sz;
		dnodes[r].p = l;
		return true;
	}

	ll size (const ll x) {
		return dnodes[find(x)].sz;
	}
};

void solve() {
	f_init(n*2+5);
	dsu g(n);

	for (ll i = 0; i < m; i++) {
		g.unite(a[i], b[i]);
	}

	vector<map<char, ll>> cnts(n); // cnts[v][c] := count of i s.t. g.find(i) == v && s[i] == c
	bool hassameswap = false;
	for (ll i = 0; i < n; i++) {
		cnts[g.find(i)][s[i]] += 1;
		if (cnts[g.find(i)][s[i]] >= 2) hassameswap = true;
	}

	bool ishalf = (!hassameswap);
	mint ans = 1;
	for (ll i = 0; i < n; i++) {
		if (cnts[i].empty()) continue;

		ll sz = g.size(i);
		for (const auto &[ch, r] : cnts[i]) {
			ans *= ncr(sz, r);
			sz -= r;
		}
		assert(sz == 0);
	}
	if (ishalf) ans /= 2;

	output(ans);
	return;
}

int main (void) {
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);

	cin >> n >> m;
	cin >> s;
	a.resize(m);
	b.resize(m);
	for (ll i = 0; i < m; i++) {
		cin >> a[i] >> b[i];
		--a[i];
		--b[i];
	}

	solve();

	return 0;
}
